import sys
import traceback as tb_module
from rich.traceback import Traceback
from rich.console import Console
from io import StringIO

def test_exception_notes():
    # Python 3.11+ feature: Exception.__notes__
    try:
        try:
            raise ValueError("Main error message")
        except ValueError as e:
            if hasattr(e, "__notes__"):
                e.__notes__ = "Additional context notes"
            raise e
    except ValueError as e:
        exc_type, exc_value, exc_traceback = sys.exc_info()

        console = Console(file=StringIO())
        # Use Traceback.extract to get the rich traceback structure
        rich_tb = Traceback.extract(exc_type, exc_value, exc_traceback)
        # Create the Traceback object
        tb = Traceback(rich_tb)

        console.print(tb)
        output = console.file.getvalue()

        if hasattr(e, "__notes__"):
            assert "Additional context notes" in output, f"Exception notes should be rendered in the traceback. Output: {output}"
        else:
            print("Python version < 3.11, skipping notes check")

if __name__ == "__main__":
    try:
        test_exception_notes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)

